import type { ServiceSlug } from "@/config/services";
import type { ProjectImage } from "@/lib/cms/types";

/**
 * Static photos shipped in /public (derivatives generated by
 * scripts/optimise-static-images.ts). A project photo is used only when the
 * project has no cover uploaded through /admin — an uploaded cover always wins.
 */
function staticImage(dir: string, base: string, widths: number[], h: (w: number) => number, alt: string): ProjectImage {
  const largest = widths[widths.length - 1];
  return {
    id: `static:${dir}/${base}`,
    src: `/${dir}/${base}-${largest}.webp`,
    srcSet: widths.map((w) => `/${dir}/${base}-${w}.webp ${w}w`).join(", "),
    width: largest,
    height: h(largest),
    alt,
    isCover: true,
  };
}

const project = (base: string, alt: string) => staticImage("projects", base, [480, 960, 1440], (w) => (w * 2) / 3, alt);
const service = (base: string, alt: string) => staticImage("services", base, [480, 960], (w) => (w * 3) / 4, alt);

